/**
 * String `format` predicates — the ONE source of truth shared by the
 * validator (`schema.ts`) and the inference sniffers (`infer.ts`). Keeping
 * them here (a tiny, dependency-free module) guarantees a sniffed format is
 * always a subset of the enforced one, so an inferred schema can never reject
 * its own sample — and keeps the `tosijs-schema/infer` subpath from dragging
 * in the validator.
 */
export const RX_EMOJI_ATOM = '\\p{Extended_Pictographic}'

// RFC 3339 full-date (`YYYY-MM-DD`), calendar-valid incl. day-in-month, so a
// value we accept is one Ajv/ajv-formats and other conforming validators also
// accept — inferred/authored schemas must travel out of this library intact.
// Regex + day table hoisted to module scope (this runs per value on the
// date/date-time hot path — same discipline as PATTERN_CACHE below).
const RX_FULL_DATE = /^(\d{4})-(\d{2})-(\d{2})$/
const DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
const isFullDate = (v: string): boolean => {
  const m = RX_FULL_DATE.exec(v)
  if (!m) return false
  const y = +m[1]!,
    mo = +m[2]!,
    d = +m[3]!
  if (mo < 1 || mo > 12 || d < 1) return false
  const max =
    mo === 2 && y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0)
      ? 29
      : DAYS_IN_MONTH[mo - 1]!
  return d <= max
}

const RX_DATE_TIME =
  /^(\d{4}-\d{2}-\d{2})[Tt](\d{2}):(\d{2}):(\d{2})(?:\.\d+)?(?:[Zz]|[+-]\d{2}:\d{2})$/

export const FORMAT_VALIDATORS: Record<string, (v: string) => boolean> = {
  email: (v) => /^\S+@\S+\.\S+$/.test(v),
  uuid: (v) =>
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v),
  uri: (v) => {
    try {
      new URL(v)
      return true
    } catch {
      return false
    }
  },
  ipv4: (v) =>
    /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/.test(
      v
    ),
  date: isFullDate,
  // RFC 3339 date-time: full-date "T" time with seconds and a Z/offset.
  // NOT `!isNaN(Date.parse(v))` — that accepted `2020-01-01`, `2020-01-01 10:00`,
  // `Jan 1 2020`, none of which are RFC 3339, producing schemas other tools reject.
  'date-time': (v) => {
    const m = RX_DATE_TIME.exec(v)
    if (!m || !isFullDate(m[1]!)) return false
    const hh = +m[2]!,
      mm = +m[3]!,
      ss = +m[4]!
    if (hh > 23 || mm > 59) return false
    // a leap second (`:60`) is legal only at 23:59, matching ajv-formats
    return ss <= 59 || (ss === 60 && hh === 23 && mm === 59)
  },
  emoji: (v) => new RegExp(RX_EMOJI_ATOM, 'u').test(v),
}

/** the formats `validate` actually enforces (and thus that inference may emit) */
export const ENFORCED_FORMATS: ReadonlySet<string> = new Set(
  Object.keys(FORMAT_VALIDATORS)
)

// Compile `pattern` once and reuse it — the validator re-walks the same schema
// node for every element of a large array, so compiling per value is pure
// waste. Bounded so a stream of distinct runtime schemas (patterns off the
// wire) can't grow it without limit; on overflow the cache simply resets.
// Throws on an invalid pattern (never caches it) — callers decide fail-closed.
const PATTERN_CACHE = new Map<string, RegExp>()
const PATTERN_CACHE_MAX = 500
export const compilePattern = (pattern: string, emoji: boolean): RegExp => {
  const flags = emoji ? 'u' : ''
  const key = flags + '�' + pattern
  let re = PATTERN_CACHE.get(key)
  if (re === undefined) {
    re = new RegExp(pattern, flags)
    if (PATTERN_CACHE.size >= PATTERN_CACHE_MAX) PATTERN_CACHE.clear()
    PATTERN_CACHE.set(key, re)
  }
  return re
}
